#include <stdarg.h>

void abort(void);
void exit(int);

va_list global;

void vat(va_list param, ...) {
  va_list local;

  va_start(local, param);
  va_copy(global, local);
  va_copy(param, local);
  if (va_arg(local, int) != 1)
    abort();
  va_end(local);
  if (va_arg(global, int) != 1)
    abort();
  va_end(global);
  if (va_arg(param, int) != 1)
    abort();
  va_end(param);

  va_start(param, param);
  va_start(global, param);
  va_copy(local, param);
  if (va_arg(local, int) != 1)
    abort();
  va_end(local);
  va_copy(local, global);
  if (va_arg(local, int) != 1)
    abort();
  va_end(local);
  if (va_arg(global, int) != 1)
    abort();
  va_end(global);
  if (va_arg(param, int) != 1)
    abort();
  va_end(param);
}

int main(void) {
  va_list t;
  vat(t, 1);
  exit(0);
}


